def append_once(path, record):
    import fcntl
    import json
    import math
    import os

    def validate(value):
        if value is None or type(value) in (str, bool, int):
            return
        if type(value) is float:
            if not math.isfinite(value):
                raise ValueError("non-finite JSON number")
            return
        if type(value) is list:
            for item in value:
                validate(item)
            return
        if type(value) is dict:
            for key, item in value.items():
                if type(key) is not str:
                    raise ValueError("JSON object keys must be strings")
                validate(item)
            return
        raise ValueError("unsupported JSON value")

    def encode(row):
        if type(row) is not dict:
            raise ValueError("record must be a JSON dict")
        if not isinstance(row.get("id"), str) or not row["id"]:
            raise ValueError("record id must be a nonempty string")
        validate(row)
        return json.dumps(row, allow_nan=False, sort_keys=True,
                          ensure_ascii=True, separators=(",", ":"))

    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise ValueError("duplicate JSON object key")
            result[key] = value
        return result

    def bad_constant(value):
        raise ValueError("non-finite JSON constant: " + value)

    encoded = encode(record)
    new_id = record["id"]
    payload = (encoded + "\n").encode("ascii")
    fd = os.open(path, os.O_RDWR | os.O_CREAT | os.O_APPEND, 0o600)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
        with os.fdopen(os.dup(fd), "rb") as stream:
            raw = stream.read()
        seen = {}
        lines = raw.split(b"\n")
        if lines and lines[-1] == b"":
            lines.pop()
        for line in lines:
            row = json.loads(line.decode("utf-8"), object_pairs_hook=pairs,
                             parse_constant=bad_constant)
            canonical = encode(row)
            row_id = row["id"]
            if row_id in seen:
                raise ValueError("duplicate ledger id")
            seen[row_id] = canonical
        if new_id in seen:
            if seen[new_id] != encoded:
                raise ValueError("existing id has changed content")
            return False
        if raw and not raw.endswith(b"\n"):
            payload = b"\n" + payload
        pending = memoryview(payload)
        while pending:
            count = os.write(fd, pending)
            if count <= 0:
                raise OSError("append made no progress")
            pending = pending[count:]
        os.fsync(fd)
        return True
    finally:
        os.close(fd)
